import { useState } from "react";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";

export default function Register() {

const navigate = useNavigate();

const [form,setForm] = useState({

name:"",

email:"",

password:"",

role:"Student",

otp:""

});

const [msg,setMsg] = useState("");


const handleChange=(e)=>{

setForm({

...form,

[e.target.name]:e.target.value

});

};


const sendOtp = async()=>{

try{

const res = await axios.post(

"http://localhost:5000/api/auth/send-otp",

{

email:form.email

}

);

setMsg(res.data.message);

alert("OTP Sent Successfully");

}

catch(err){

setMsg("OTP Failed");

alert("OTP Failed");

}

};



const handleRegister = async(e)=>{

e.preventDefault();

try{

const res = await axios.post(

"http://localhost:5000/api/auth/register",

form

);

alert(res.data.message);

navigate("/login");

}

catch(err){

alert(

err.response?.data?.message ||

"Registration Failed"

);

}

};



return(

<div

style={{

height:"100vh",

display:"flex",

justifyContent:"center",

alignItems:"center",

background:"#0f172a"

}}

>

<form

onSubmit={handleRegister}

style={{

background:"white",

padding:"30px",

width:"400px",

borderRadius:"15px"

}}

>

<h1>

RBAC Register

</h1>



<input

type="text"

name="name"

placeholder="Full Name"

onChange={handleChange}

style={inputStyle}

required

/>



<input

type="email"

name="email"

placeholder="Email"

onChange={handleChange}

style={inputStyle}

required

/>



<button

type="button"

onClick={sendOtp}

style={otpButton}

>

Send OTP

</button>



<input

type="text"

name="otp"

placeholder="Enter OTP"

onChange={handleChange}

style={inputStyle}

required

/>



<input

type="password"

name="password"

placeholder="Password"

onChange={handleChange}

style={inputStyle}

required

/>



<select

name="role"

onChange={handleChange}

style={inputStyle}

>

<option>

Student

</option>

<option>

Instructor

</option>

<option>

Admin

</option>

</select>



<button

type="submit"

style={registerButton}

>

Register

</button>



<p>

Already have account ?

<Link to="/login">

 Login

</Link>

</p>


<h3>

{msg}

</h3>


</form>

</div>

)

}



const inputStyle={

width:"100%",

padding:"12px",

marginBottom:"15px"

};



const otpButton={

width:"100%",

padding:"12px",

background:"#2563eb",

color:"white",

border:"none",

marginBottom:"15px",

cursor:"pointer"

};



const registerButton={

width:"100%",

padding:"12px",

background:"#16a34a",

color:"white",

border:"none",

cursor:"pointer"

};
